/* store-link (reconstructed in-store stock system side) — generated by tools/snapshots/ec-tackleberry-api/build-src.js from store-link/ */
(function (root) {
  var SRC = {"files":{"link.mjs":"// 店舗の在庫システム ⇄ ＠ベリーネット（EC-CUBE 4.3 の Web API：GraphQL・OAuth2.0・WebHook）\n//   node link.mjs serve          OAuth のコールバックと WebHook の受け口（:3100）\n//   node link.mjs authorize      認可の URL（管理画面で「許可」→ /callback）\n//   node link.mjs stock <csv>    POS の販売・取置 → updateProductStock\n//   node link.mjs orders         新規受付の注文の取りこぼし確認（定期実行）\n//   node link.mjs ship <csv>     店舗の出荷実績 → updateShipped（出荷完了メール）\nimport fs from 'node:fs';\nimport http from 'node:http';\nimport crypto from 'node:crypto';\nimport { log, readCsv, body } from './lib/util.mjs';\n\nprocess.loadEnvFile();\nconst { EC_URL, CLIENT_ID, CLIENT_SECRET, REDIRECT_URI, WEBHOOK_SECRET } = process.env;\nconst TOKEN = 'var/token.json';\nconst PICKED = 'var/picked.json';\nconst gql = (name) => fs.readFileSync(`graphql/${name}.graphql`, 'utf8');\nfs.mkdirSync('var', { recursive: true });\n\n/* ---------------------------------------------------------- OAuth2.0（Authorization Code） */\nasync function tokenRequest(params) {\n  const res = await fetch(`${EC_URL}/token`, {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },\n    body: new URLSearchParams({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, ...params }),\n  });\n  const json = await res.json();\n  if (!res.ok) throw new Error(`token ${res.status} ${json.error}: ${json.error_description ?? json.message}`);\n  const token = { ...json, expires_at: Date.now() + json.expires_in * 1000 };\n  fs.writeFileSync(TOKEN, JSON.stringify(token, null, 2));\n  return token;\n}\n\nasync function accessToken() {\n  let t = JSON.parse(fs.readFileSync(TOKEN, 'utf8'));\n  if (Date.now() > t.expires_at - 60_000) {\n    log('アクセストークンの期限切れ → リフレッシュトークンで更新');\n    t = await tokenRequest({ grant_type: 'refresh_token', refresh_token: t.refresh_token });\n  }\n  return t.access_token;\n}\n\n/* ---------------------------------------------------------- GraphQL（/api） */\nasync function api(query, variables = {}) {\n  const res = await fetch(`${EC_URL}/api`, {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${await accessToken()}` },\n    body: JSON.stringify({ query, variables }),\n  });\n  const json = await res.json();\n  if (json.errors) throw new Error(json.errors.map((e) => e.message).join(' / '));\n  return json.data;\n}\n\n/* ---------------------------------------------------------- 在庫台帳・出荷指示 */\nconst ledger = Object.fromEntries(readCsv('data/ledger.csv').map((r) => [r.商品コード, r]));\nconst picked = new Set(fs.existsSync(PICKED) ? JSON.parse(fs.readFileSync(PICKED, 'utf8')) : []);\n\nasync function pick(id) {\n  if (picked.has(String(id))) return;\n  const { order } = await api(gql('order'), { id });\n  if (order.OrderStatus.id !== '1') return; // 新規受付だけ（購入処理中の仮受注は除く）\n  for (const s of order.Shippings) {\n    for (const item of s.OrderItems.filter((i) => i.product_code)) {\n      const at = ledger[item.product_code];\n      log(`出荷指示 受注 ${order.order_no} → 店舗 ${at.店舗}（棚 ${at.棚番}）${item.product_name} 出荷 ID ${s.id}`);\n      fs.mkdirSync('outbox', { recursive: true });\n      fs.appendFileSync(`outbox/picking-${at.店舗}.csv`,\n        [order.order_no, s.id, item.product_code, item.product_name, at.棚番].join(',') + '\\n');\n    }\n  }\n  picked.add(String(id));\n  fs.writeFileSync(PICKED, JSON.stringify([...picked]));\n}\n\n/* ---------------------------------------------------------- WebHook（X-ECCUBE-Signature） */\nfunction verify(raw, sig) {\n  const mine = crypto.createHmac('sha256', WEBHOOK_SECRET).update(raw).digest('hex');\n  return typeof sig === 'string' && sig.length === mine.length\n    && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(mine));\n}\n\nconst page = (title, text) => `<!doctype html><meta charset=\"utf-8\"><title>store-link</title>\n<body style=\"font:16px sans-serif;margin:48px\"><h1 style=\"font-size:22px\">${title}</h1><p>${text}</p></body>`;\n\nconst [cmd, arg] = process.argv.slice(2);\n\nif (cmd === 'serve') {\n  http.createServer(async (req, res) => {\n    const url = new URL(req.url, REDIRECT_URI);\n    if (url.pathname === '/callback') {\n      if (url.searchParams.get('state') !== fs.readFileSync('var/state', 'utf8')) {\n        res.writeHead(400).end('state mismatch');\n        return;\n      }\n      const code = url.searchParams.get('code');\n      const t = await tokenRequest({ grant_type: 'authorization_code', code, redirect_uri: REDIRECT_URI });\n      const jwt = JSON.parse(Buffer.from(t.access_token.split('.')[1], 'base64url'));\n      log(`認可 OK（${jwt.sub}・scope ${jwt.scopes.join(' ')}）トークンを ${TOKEN} に保存`);\n      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });\n      res.end(page('＠ベリーネットの API を認可しました', `scope: ${jwt.scopes.join(' ')} — このタブは閉じてかまいません。`));\n      return;\n    }\n    if (url.pathname === '/webhook' && req.method === 'POST') {\n      const raw = await body(req);\n      if (!verify(raw, req.headers['x-eccube-signature'])) {\n        log('WebHook 署名が一致しません → 401');\n        res.writeHead(401).end();\n        return;\n      }\n      res.writeHead(200).end(); // 先に 200 を返し、処理はそのあと\n      const events = JSON.parse(raw);\n      log(`WebHook ${events.map((e) => `${e.entity}#${e.id} ${e.action}`).join(', ')}`);\n      for (const id of new Set(events.filter((e) => e.entity === 'order').map((e) => e.id))) {\n        await pick(id).catch((e) => log(`受注 ${id} 失敗: ${e.message}`));\n      }\n      return;\n    }\n    res.writeHead(404).end();\n  }).listen(new URL(REDIRECT_URI).port, () => log(`store-link ${new URL(REDIRECT_URI).origin}（/callback /webhook）`));\n}\n\nif (cmd === 'authorize') {\n  const state = crypto.randomBytes(8).toString('hex');\n  fs.writeFileSync('var/state', state);\n  const q = new URLSearchParams({ response_type: 'code', client_id: CLIENT_ID, redirect_uri: REDIRECT_URI, scope: 'read write', state });\n  console.log(`${EC_URL}/admin/authorize?${q}`);\n}\n\nif (cmd === 'stock') {\n  // POS の販売・取置：商品コード（店舗のバーコード）ごとの在庫数。中古品は 1 点もの\n  for (const row of readCsv(arg)) {\n    try {\n      const { updateProductStock: p } = await api(gql('update-stock'), { code: row.商品コード, stock: Number(row.在庫数) });\n      log(`在庫 ${p.code} → ${p.stock}（${row.区分}・店舗 ${row.店舗}）`);\n    } catch (e) {\n      log(`在庫 ${row.商品コード} 失敗: ${e.message}`);\n      process.exitCode = 1;\n    }\n  }\n}\n\nif (cmd === 'orders') {\n  // WebHook が届かなかったときの取りこぼし対策：新規受付の注文をまとめて確認\n  try {\n    const { orders } = await api(gql('orders'));\n    log(`新規受付 ${orders.nodes.length} 件（出荷指示済み ${orders.nodes.filter((o) => picked.has(o.id)).length} 件）`);\n    for (const o of orders.nodes) await pick(o.id);\n  } catch (e) {\n    log(`取りこぼし確認 失敗: ${e.message}`);\n    process.exitCode = 1;\n  }\n}\n\nif (cmd === 'ship') {\n  // 店舗の出荷実績：出荷 ID・配送業者・お問い合わせ番号 → 出荷済み・出荷完了メール\n  for (const row of readCsv(arg)) {\n    try {\n      const { updateShipped: s } = await api(gql('update-shipped'), {\n        id: row.出荷ID, delivery: row.配送業者, tracking: row.お問い合わせ番号, note: `店舗 ${row.店舗} から出荷`,\n      });\n      log(`出荷 受注 ${row.受注番号}（出荷 ID ${s.id}）${s.shipping_delivery_name} ${s.tracking_number} メール送信 ${s.mail_send_date ? '済' : '-'}`);\n    } catch (e) {\n      log(`出荷 受注 ${row.受注番号} 失敗: ${e.message}`);\n      process.exitCode = 1;\n    }\n  }\n}\n","lib/util.mjs":"// store-link の小さな道具：ログ（画面と logs/link-YYYYMMDD.log）、CSV（1 行目が見出し）、リクエストの本文\nimport fs from 'node:fs';\n\nconst pad = (n) => String(n).padStart(2, '0');\n\nexport function log(msg) {\n  const d = new Date();\n  const time = `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;\n  const day = `${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}`;\n  console.log(`[${time}] ${msg}`);\n  fs.mkdirSync('logs', { recursive: true });\n  fs.appendFileSync(`logs/link-${day}.log`, `${day} ${time} ${msg}\\n`);\n}\n\nexport function readCsv(file) {\n  const [head, ...rows] = fs.readFileSync(file, 'utf8').trim().split(/\\r?\\n/);\n  const keys = head.split(',');\n  return rows.map((r) => Object.fromEntries(r.split(',').map((v, i) => [keys[i], v])));\n}\n\nexport async function body(req) {\n  const chunks = [];\n  for await (const c of req) chunks.push(c);\n  return Buffer.concat(chunks).toString('utf8');\n}\n","graphql/update-stock.graphql":"# 店舗の在庫数を EC へ（中古品は 1 点もの：在庫は無制限にしない）\nmutation UpdateStock($code: String!, $stock: Int!) {\n  updateProductStock(code: $code, stock: $stock, stock_unlimited: false) {\n    code\n    stock\n    stock_unlimited\n  }\n}\n","graphql/order.graphql":"# 受注 1 件：対応状況と、出荷ごとの商品（商品コード → 在庫店舗）\nquery Order($id: ID!) {\n  order(id: $id) {\n    id\n    order_no\n    OrderStatus {\n      id\n      name\n    }\n    Shippings {\n      id\n      OrderItems {\n        product_code\n        product_name\n        quantity\n      }\n    }\n  }\n}\n","graphql/orders.graphql":"# 新規受付（対応状況 1）の注文：WebHook が届かなかった注文の取りこぼし確認\nquery NewOrders {\n  orders(status: [\"1\"]) {\n    totalCount\n    nodes {\n      id\n      order_no\n    }\n  }\n}\n","graphql/update-shipped.graphql":"# 出荷済みにして出荷完了メール（出荷日は実行日時）\nmutation Ship($id: ID!, $delivery: String, $tracking: String, $note: String) {\n  updateShipped(\n    id: $id\n    shipping_delivery_name: $delivery\n    tracking_number: $tracking\n    note: $note\n    is_send_mail: true\n  ) {\n    id\n    shipping_date\n    shipping_delivery_name\n    tracking_number\n    mail_send_date\n  }\n}\n",".env.example":"# ＠ベリーネット（EC-CUBE 4.3）の Web API\nEC_URL=http://localhost:8080\n# 管理画面 › 設定 › API管理 › OAuth管理 で登録したクライアント\nCLIENT_ID=\nCLIENT_SECRET=\nREDIRECT_URI=http://localhost:3100/callback\n# 管理画面 › 設定 › API管理 › WebHook管理 のシークレット\nWEBHOOK_SECRET=\n"},"link":{"1":"// 店舗の在庫システム ⇄ ＠ベリーネット（EC-CUBE 4.3 の Web API：GraphQL・OAuth2.0・WebHook）\n//   node link.mjs serve          OAuth のコールバックと WebHook の受け口（:3100）\n//   node link.mjs authorize      認可の URL（管理画面で「許可」→ /callback）\n//   node link.mjs stock <csv>    POS の販売・取置 → updateProductStock\nimport fs from 'node:fs';\nimport http from 'node:http';\nimport crypto from 'node:crypto';\nimport { log, readCsv, body } from './lib/util.mjs';\n\nprocess.loadEnvFile();\nconst { EC_URL, CLIENT_ID, CLIENT_SECRET, REDIRECT_URI, WEBHOOK_SECRET } = process.env;\nconst TOKEN = 'var/token.json';\nconst gql = (name) => fs.readFileSync(`graphql/${name}.graphql`, 'utf8');\nfs.mkdirSync('var', { recursive: true });\n\n/* ---------------------------------------------------------- OAuth2.0（Authorization Code） */\nasync function tokenRequest(params) {\n  const res = await fetch(`${EC_URL}/token`, {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },\n    body: new URLSearchParams({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, ...params }),\n  });\n  const json = await res.json();\n  if (!res.ok) throw new Error(`token ${res.status} ${json.error}: ${json.error_description ?? json.message}`);\n  const token = { ...json, expires_at: Date.now() + json.expires_in * 1000 };\n  fs.writeFileSync(TOKEN, JSON.stringify(token, null, 2));\n  return token;\n}\n\nasync function accessToken() {\n  let t = JSON.parse(fs.readFileSync(TOKEN, 'utf8'));\n  if (Date.now() > t.expires_at - 60_000) {\n    log('アクセストークンの期限切れ → リフレッシュトークンで更新');\n    t = await tokenRequest({ grant_type: 'refresh_token', refresh_token: t.refresh_token });\n  }\n  return t.access_token;\n}\n\n/* ---------------------------------------------------------- GraphQL（/api） */\nasync function api(query, variables = {}) {\n  const res = await fetch(`${EC_URL}/api`, {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${await accessToken()}` },\n    body: JSON.stringify({ query, variables }),\n  });\n  const json = await res.json();\n  if (json.errors) throw new Error(json.errors.map((e) => e.message).join(' / '));\n  return json.data;\n}\n\nconst page = (title, text) => `<!doctype html><meta charset=\"utf-8\"><title>store-link</title>\n<body style=\"font:16px sans-serif;margin:48px\"><h1 style=\"font-size:22px\">${title}</h1><p>${text}</p></body>`;\n\nconst [cmd, arg] = process.argv.slice(2);\n\nif (cmd === 'serve') {\n  http.createServer(async (req, res) => {\n    const url = new URL(req.url, REDIRECT_URI);\n    if (url.pathname === '/callback') {\n      if (url.searchParams.get('state') !== fs.readFileSync('var/state', 'utf8')) {\n        res.writeHead(400).end('state mismatch');\n        return;\n      }\n      const code = url.searchParams.get('code');\n      const t = await tokenRequest({ grant_type: 'authorization_code', code, redirect_uri: REDIRECT_URI });\n      const jwt = JSON.parse(Buffer.from(t.access_token.split('.')[1], 'base64url'));\n      log(`認可 OK（${jwt.sub}・scope ${jwt.scopes.join(' ')}）トークンを ${TOKEN} に保存`);\n      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });\n      res.end(page('＠ベリーネットの API を認可しました', `scope: ${jwt.scopes.join(' ')} — このタブは閉じてかまいません。`));\n      return;\n    }\n    res.writeHead(404).end();\n  }).listen(new URL(REDIRECT_URI).port, () => log(`store-link ${new URL(REDIRECT_URI).origin}（/callback /webhook）`));\n}\n\nif (cmd === 'authorize') {\n  const state = crypto.randomBytes(8).toString('hex');\n  fs.writeFileSync('var/state', state);\n  const q = new URLSearchParams({ response_type: 'code', client_id: CLIENT_ID, redirect_uri: REDIRECT_URI, scope: 'read write', state });\n  console.log(`${EC_URL}/admin/authorize?${q}`);\n}\n\nif (cmd === 'stock') {\n  // POS の販売・取置：商品コード（店舗のバーコード）ごとの在庫数。中古品は 1 点もの\n  for (const row of readCsv(arg)) {\n    try {\n      const { updateProductStock: p } = await api(gql('update-stock'), { code: row.商品コード, stock: Number(row.在庫数) });\n      log(`在庫 ${p.code} → ${p.stock}（${row.区分}・店舗 ${row.店舗}）`);\n    } catch (e) {\n      log(`在庫 ${row.商品コード} 失敗: ${e.message}`);\n      process.exitCode = 1;\n    }\n  }\n}\n","2":"// 店舗の在庫システム ⇄ ＠ベリーネット（EC-CUBE 4.3 の Web API：GraphQL・OAuth2.0・WebHook）\n//   node link.mjs serve          OAuth のコールバックと WebHook の受け口（:3100）\n//   node link.mjs authorize      認可の URL（管理画面で「許可」→ /callback）\n//   node link.mjs stock <csv>    POS の販売・取置 → updateProductStock\nimport fs from 'node:fs';\nimport http from 'node:http';\nimport crypto from 'node:crypto';\nimport { log, readCsv, body } from './lib/util.mjs';\n\nprocess.loadEnvFile();\nconst { EC_URL, CLIENT_ID, CLIENT_SECRET, REDIRECT_URI, WEBHOOK_SECRET } = process.env;\nconst TOKEN = 'var/token.json';\nconst PICKED = 'var/picked.json';\nconst gql = (name) => fs.readFileSync(`graphql/${name}.graphql`, 'utf8');\nfs.mkdirSync('var', { recursive: true });\n\n/* ---------------------------------------------------------- OAuth2.0（Authorization Code） */\nasync function tokenRequest(params) {\n  const res = await fetch(`${EC_URL}/token`, {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },\n    body: new URLSearchParams({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, ...params }),\n  });\n  const json = await res.json();\n  if (!res.ok) throw new Error(`token ${res.status} ${json.error}: ${json.error_description ?? json.message}`);\n  const token = { ...json, expires_at: Date.now() + json.expires_in * 1000 };\n  fs.writeFileSync(TOKEN, JSON.stringify(token, null, 2));\n  return token;\n}\n\nasync function accessToken() {\n  let t = JSON.parse(fs.readFileSync(TOKEN, 'utf8'));\n  if (Date.now() > t.expires_at - 60_000) {\n    log('アクセストークンの期限切れ → リフレッシュトークンで更新');\n    t = await tokenRequest({ grant_type: 'refresh_token', refresh_token: t.refresh_token });\n  }\n  return t.access_token;\n}\n\n/* ---------------------------------------------------------- GraphQL（/api） */\nasync function api(query, variables = {}) {\n  const res = await fetch(`${EC_URL}/api`, {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${await accessToken()}` },\n    body: JSON.stringify({ query, variables }),\n  });\n  const json = await res.json();\n  if (json.errors) throw new Error(json.errors.map((e) => e.message).join(' / '));\n  return json.data;\n}\n\n/* ---------------------------------------------------------- 在庫台帳・出荷指示 */\nconst ledger = Object.fromEntries(readCsv('data/ledger.csv').map((r) => [r.商品コード, r]));\nconst picked = new Set(fs.existsSync(PICKED) ? JSON.parse(fs.readFileSync(PICKED, 'utf8')) : []);\n\nasync function pick(id) {\n  if (picked.has(String(id))) return;\n  const { order } = await api(gql('order'), { id });\n  if (order.OrderStatus.id !== '1') return; // 新規受付だけ（購入処理中の仮受注は除く）\n  for (const s of order.Shippings) {\n    for (const item of s.OrderItems.filter((i) => i.product_code)) {\n      const at = ledger[item.product_code];\n      log(`出荷指示 受注 ${order.order_no} → 店舗 ${at.店舗}（棚 ${at.棚番}）${item.product_name} 出荷 ID ${s.id}`);\n      fs.mkdirSync('outbox', { recursive: true });\n      fs.appendFileSync(`outbox/picking-${at.店舗}.csv`,\n        [order.order_no, s.id, item.product_code, item.product_name, at.棚番].join(',') + '\\n');\n    }\n  }\n  picked.add(String(id));\n  fs.writeFileSync(PICKED, JSON.stringify([...picked]));\n}\n\n/* ---------------------------------------------------------- WebHook（X-ECCUBE-Signature） */\nfunction verify(raw, sig) {\n  const mine = crypto.createHmac('sha256', WEBHOOK_SECRET).update(raw).digest('hex');\n  return typeof sig === 'string' && sig.length === mine.length\n    && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(mine));\n}\n\nconst page = (title, text) => `<!doctype html><meta charset=\"utf-8\"><title>store-link</title>\n<body style=\"font:16px sans-serif;margin:48px\"><h1 style=\"font-size:22px\">${title}</h1><p>${text}</p></body>`;\n\nconst [cmd, arg] = process.argv.slice(2);\n\nif (cmd === 'serve') {\n  http.createServer(async (req, res) => {\n    const url = new URL(req.url, REDIRECT_URI);\n    if (url.pathname === '/callback') {\n      if (url.searchParams.get('state') !== fs.readFileSync('var/state', 'utf8')) {\n        res.writeHead(400).end('state mismatch');\n        return;\n      }\n      const code = url.searchParams.get('code');\n      const t = await tokenRequest({ grant_type: 'authorization_code', code, redirect_uri: REDIRECT_URI });\n      const jwt = JSON.parse(Buffer.from(t.access_token.split('.')[1], 'base64url'));\n      log(`認可 OK（${jwt.sub}・scope ${jwt.scopes.join(' ')}）トークンを ${TOKEN} に保存`);\n      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });\n      res.end(page('＠ベリーネットの API を認可しました', `scope: ${jwt.scopes.join(' ')} — このタブは閉じてかまいません。`));\n      return;\n    }\n    if (url.pathname === '/webhook' && req.method === 'POST') {\n      const raw = await body(req);\n      if (!verify(raw, req.headers['X-ECCUBE-Signature'])) {\n        log('WebHook 署名が一致しません → 401');\n        res.writeHead(401).end();\n        return;\n      }\n      res.writeHead(200).end(); // 先に 200 を返し、処理はそのあと\n      const events = JSON.parse(raw);\n      log(`WebHook ${events.map((e) => `${e.entity}#${e.id} ${e.action}`).join(', ')}`);\n      for (const id of new Set(events.filter((e) => e.entity === 'order').map((e) => e.id))) {\n        await pick(id).catch((e) => log(`受注 ${id} 失敗: ${e.message}`));\n      }\n      return;\n    }\n    res.writeHead(404).end();\n  }).listen(new URL(REDIRECT_URI).port, () => log(`store-link ${new URL(REDIRECT_URI).origin}（/callback /webhook）`));\n}\n\nif (cmd === 'authorize') {\n  const state = crypto.randomBytes(8).toString('hex');\n  fs.writeFileSync('var/state', state);\n  const q = new URLSearchParams({ response_type: 'code', client_id: CLIENT_ID, redirect_uri: REDIRECT_URI, scope: 'read write', state });\n  console.log(`${EC_URL}/admin/authorize?${q}`);\n}\n\nif (cmd === 'stock') {\n  // POS の販売・取置：商品コード（店舗のバーコード）ごとの在庫数。中古品は 1 点もの\n  for (const row of readCsv(arg)) {\n    try {\n      const { updateProductStock: p } = await api(gql('update-stock'), { code: row.商品コード, stock: Number(row.在庫数) });\n      log(`在庫 ${p.code} → ${p.stock}（${row.区分}・店舗 ${row.店舗}）`);\n    } catch (e) {\n      log(`在庫 ${row.商品コード} 失敗: ${e.message}`);\n      process.exitCode = 1;\n    }\n  }\n}\n","3":"// 店舗の在庫システム ⇄ ＠ベリーネット（EC-CUBE 4.3 の Web API：GraphQL・OAuth2.0・WebHook）\n//   node link.mjs serve          OAuth のコールバックと WebHook の受け口（:3100）\n//   node link.mjs authorize      認可の URL（管理画面で「許可」→ /callback）\n//   node link.mjs stock <csv>    POS の販売・取置 → updateProductStock\n//   node link.mjs ship <csv>     店舗の出荷実績 → updateShipped（出荷完了メール）\nimport fs from 'node:fs';\nimport http from 'node:http';\nimport crypto from 'node:crypto';\nimport { log, readCsv, body } from './lib/util.mjs';\n\nprocess.loadEnvFile();\nconst { EC_URL, CLIENT_ID, CLIENT_SECRET, REDIRECT_URI, WEBHOOK_SECRET } = process.env;\nconst TOKEN = 'var/token.json';\nconst PICKED = 'var/picked.json';\nconst gql = (name) => fs.readFileSync(`graphql/${name}.graphql`, 'utf8');\nfs.mkdirSync('var', { recursive: true });\n\n/* ---------------------------------------------------------- OAuth2.0（Authorization Code） */\nasync function tokenRequest(params) {\n  const res = await fetch(`${EC_URL}/token`, {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },\n    body: new URLSearchParams({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, ...params }),\n  });\n  const json = await res.json();\n  if (!res.ok) throw new Error(`token ${res.status} ${json.error}: ${json.error_description ?? json.message}`);\n  const token = { ...json, expires_at: Date.now() + json.expires_in * 1000 };\n  fs.writeFileSync(TOKEN, JSON.stringify(token, null, 2));\n  return token;\n}\n\nasync function accessToken() {\n  let t = JSON.parse(fs.readFileSync(TOKEN, 'utf8'));\n  if (Date.now() > t.expires_at - 60_000) {\n    log('アクセストークンの期限切れ → リフレッシュトークンで更新');\n    t = await tokenRequest({ grant_type: 'refresh_token', refresh_token: t.refresh_token });\n  }\n  return t.access_token;\n}\n\n/* ---------------------------------------------------------- GraphQL（/api） */\nasync function api(query, variables = {}) {\n  const res = await fetch(`${EC_URL}/api`, {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${await accessToken()}` },\n    body: JSON.stringify({ query, variables }),\n  });\n  const json = await res.json();\n  if (json.errors) throw new Error(json.errors.map((e) => e.message).join(' / '));\n  return json.data;\n}\n\n/* ---------------------------------------------------------- 在庫台帳・出荷指示 */\nconst ledger = Object.fromEntries(readCsv('data/ledger.csv').map((r) => [r.商品コード, r]));\nconst picked = new Set(fs.existsSync(PICKED) ? JSON.parse(fs.readFileSync(PICKED, 'utf8')) : []);\n\nasync function pick(id) {\n  if (picked.has(String(id))) return;\n  const { order } = await api(gql('order'), { id });\n  if (order.OrderStatus.id !== '1') return; // 新規受付だけ（購入処理中の仮受注は除く）\n  for (const s of order.Shippings) {\n    for (const item of s.OrderItems.filter((i) => i.product_code)) {\n      const at = ledger[item.product_code];\n      log(`出荷指示 受注 ${order.order_no} → 店舗 ${at.店舗}（棚 ${at.棚番}）${item.product_name} 出荷 ID ${s.id}`);\n      fs.mkdirSync('outbox', { recursive: true });\n      fs.appendFileSync(`outbox/picking-${at.店舗}.csv`,\n        [order.order_no, s.id, item.product_code, item.product_name, at.棚番].join(',') + '\\n');\n    }\n  }\n  picked.add(String(id));\n  fs.writeFileSync(PICKED, JSON.stringify([...picked]));\n}\n\n/* ---------------------------------------------------------- WebHook（X-ECCUBE-Signature） */\nfunction verify(raw, sig) {\n  const mine = crypto.createHmac('sha256', WEBHOOK_SECRET).update(raw).digest('hex');\n  return typeof sig === 'string' && sig.length === mine.length\n    && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(mine));\n}\n\nconst page = (title, text) => `<!doctype html><meta charset=\"utf-8\"><title>store-link</title>\n<body style=\"font:16px sans-serif;margin:48px\"><h1 style=\"font-size:22px\">${title}</h1><p>${text}</p></body>`;\n\nconst [cmd, arg] = process.argv.slice(2);\n\nif (cmd === 'serve') {\n  http.createServer(async (req, res) => {\n    const url = new URL(req.url, REDIRECT_URI);\n    if (url.pathname === '/callback') {\n      if (url.searchParams.get('state') !== fs.readFileSync('var/state', 'utf8')) {\n        res.writeHead(400).end('state mismatch');\n        return;\n      }\n      const code = url.searchParams.get('code');\n      const t = await tokenRequest({ grant_type: 'authorization_code', code, redirect_uri: REDIRECT_URI });\n      const jwt = JSON.parse(Buffer.from(t.access_token.split('.')[1], 'base64url'));\n      log(`認可 OK（${jwt.sub}・scope ${jwt.scopes.join(' ')}）トークンを ${TOKEN} に保存`);\n      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });\n      res.end(page('＠ベリーネットの API を認可しました', `scope: ${jwt.scopes.join(' ')} — このタブは閉じてかまいません。`));\n      return;\n    }\n    if (url.pathname === '/webhook' && req.method === 'POST') {\n      const raw = await body(req);\n      if (!verify(raw, req.headers['x-eccube-signature'])) {\n        log('WebHook 署名が一致しません → 401');\n        res.writeHead(401).end();\n        return;\n      }\n      res.writeHead(200).end(); // 先に 200 を返し、処理はそのあと\n      const events = JSON.parse(raw);\n      log(`WebHook ${events.map((e) => `${e.entity}#${e.id} ${e.action}`).join(', ')}`);\n      for (const id of new Set(events.filter((e) => e.entity === 'order').map((e) => e.id))) {\n        await pick(id).catch((e) => log(`受注 ${id} 失敗: ${e.message}`));\n      }\n      return;\n    }\n    res.writeHead(404).end();\n  }).listen(new URL(REDIRECT_URI).port, () => log(`store-link ${new URL(REDIRECT_URI).origin}（/callback /webhook）`));\n}\n\nif (cmd === 'authorize') {\n  const state = crypto.randomBytes(8).toString('hex');\n  fs.writeFileSync('var/state', state);\n  const q = new URLSearchParams({ response_type: 'code', client_id: CLIENT_ID, redirect_uri: REDIRECT_URI, scope: 'read write', state });\n  console.log(`${EC_URL}/admin/authorize?${q}`);\n}\n\nif (cmd === 'stock') {\n  // POS の販売・取置：商品コード（店舗のバーコード）ごとの在庫数。中古品は 1 点もの\n  for (const row of readCsv(arg)) {\n    try {\n      const { updateProductStock: p } = await api(gql('update-stock'), { code: row.商品コード, stock: Number(row.在庫数) });\n      log(`在庫 ${p.code} → ${p.stock}（${row.区分}・店舗 ${row.店舗}）`);\n    } catch (e) {\n      log(`在庫 ${row.商品コード} 失敗: ${e.message}`);\n      process.exitCode = 1;\n    }\n  }\n}\n\nif (cmd === 'ship') {\n  // 店舗の出荷実績：出荷 ID・配送業者・お問い合わせ番号 → 出荷済み・出荷完了メール\n  for (const row of readCsv(arg)) {\n    try {\n      const { updateShipped: s } = await api(gql('update-shipped'), {\n        id: row.出荷ID, delivery: row.配送業者, tracking: row.お問い合わせ番号, note: `店舗 ${row.店舗} から出荷`,\n      });\n      log(`出荷 受注 ${row.受注番号}（出荷 ID ${s.id}）${s.shipping_delivery_name} ${s.tracking_number} メール送信 ${s.mail_send_date ? '済' : '-'}`);\n    } catch (e) {\n      log(`出荷 受注 ${row.受注番号} 失敗: ${e.message}`);\n      process.exitCode = 1;\n    }\n  }\n}\n","4":"// 店舗の在庫システム ⇄ ＠ベリーネット（EC-CUBE 4.3 の Web API：GraphQL・OAuth2.0・WebHook）\n//   node link.mjs serve          OAuth のコールバックと WebHook の受け口（:3100）\n//   node link.mjs authorize      認可の URL（管理画面で「許可」→ /callback）\n//   node link.mjs stock <csv>    POS の販売・取置 → updateProductStock\n//   node link.mjs orders         新規受付の注文の取りこぼし確認（定期実行）\n//   node link.mjs ship <csv>     店舗の出荷実績 → updateShipped（出荷完了メール）\nimport fs from 'node:fs';\nimport http from 'node:http';\nimport crypto from 'node:crypto';\nimport { log, readCsv, body } from './lib/util.mjs';\n\nprocess.loadEnvFile();\nconst { EC_URL, CLIENT_ID, CLIENT_SECRET, REDIRECT_URI, WEBHOOK_SECRET } = process.env;\nconst TOKEN = 'var/token.json';\nconst PICKED = 'var/picked.json';\nconst gql = (name) => fs.readFileSync(`graphql/${name}.graphql`, 'utf8');\nfs.mkdirSync('var', { recursive: true });\n\n/* ---------------------------------------------------------- OAuth2.0（Authorization Code） */\nasync function tokenRequest(params) {\n  const res = await fetch(`${EC_URL}/token`, {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },\n    body: new URLSearchParams({ client_id: CLIENT_ID, client_secret: CLIENT_SECRET, ...params }),\n  });\n  const json = await res.json();\n  if (!res.ok) throw new Error(`token ${res.status} ${json.error}: ${json.error_description ?? json.message}`);\n  const token = { ...json, expires_at: Date.now() + json.expires_in * 1000 };\n  fs.writeFileSync(TOKEN, JSON.stringify(token, null, 2));\n  return token;\n}\n\nasync function accessToken() {\n  let t = JSON.parse(fs.readFileSync(TOKEN, 'utf8'));\n  if (Date.now() > t.expires_at - 60_000) {\n    log('アクセストークンの期限切れ → リフレッシュトークンで更新');\n    t = await tokenRequest({ grant_type: 'refresh_token', refresh_token: t.refresh_token });\n  }\n  return t.access_token;\n}\n\n/* ---------------------------------------------------------- GraphQL（/api） */\nasync function api(query, variables = {}) {\n  const res = await fetch(`${EC_URL}/api`, {\n    method: 'POST',\n    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${await accessToken()}` },\n    body: JSON.stringify({ query, variables }),\n  });\n  const json = await res.json();\n  if (json.errors) throw new Error(json.errors.map((e) => e.message).join(' / '));\n  return json.data;\n}\n\n/* ---------------------------------------------------------- 在庫台帳・出荷指示 */\nconst ledger = Object.fromEntries(readCsv('data/ledger.csv').map((r) => [r.商品コード, r]));\nconst picked = new Set(fs.existsSync(PICKED) ? JSON.parse(fs.readFileSync(PICKED, 'utf8')) : []);\n\nasync function pick(id) {\n  if (picked.has(String(id))) return;\n  const { order } = await api(gql('order'), { id });\n  if (order.OrderStatus.id !== '1') return; // 新規受付だけ（購入処理中の仮受注は除く）\n  for (const s of order.Shippings) {\n    for (const item of s.OrderItems.filter((i) => i.product_code)) {\n      const at = ledger[item.product_code];\n      log(`出荷指示 受注 ${order.order_no} → 店舗 ${at.店舗}（棚 ${at.棚番}）${item.product_name} 出荷 ID ${s.id}`);\n      fs.mkdirSync('outbox', { recursive: true });\n      fs.appendFileSync(`outbox/picking-${at.店舗}.csv`,\n        [order.order_no, s.id, item.product_code, item.product_name, at.棚番].join(',') + '\\n');\n    }\n  }\n  picked.add(String(id));\n  fs.writeFileSync(PICKED, JSON.stringify([...picked]));\n}\n\n/* ---------------------------------------------------------- WebHook（X-ECCUBE-Signature） */\nfunction verify(raw, sig) {\n  const mine = crypto.createHmac('sha256', WEBHOOK_SECRET).update(raw).digest('hex');\n  return typeof sig === 'string' && sig.length === mine.length\n    && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(mine));\n}\n\nconst page = (title, text) => `<!doctype html><meta charset=\"utf-8\"><title>store-link</title>\n<body style=\"font:16px sans-serif;margin:48px\"><h1 style=\"font-size:22px\">${title}</h1><p>${text}</p></body>`;\n\nconst [cmd, arg] = process.argv.slice(2);\n\nif (cmd === 'serve') {\n  http.createServer(async (req, res) => {\n    const url = new URL(req.url, REDIRECT_URI);\n    if (url.pathname === '/callback') {\n      if (url.searchParams.get('state') !== fs.readFileSync('var/state', 'utf8')) {\n        res.writeHead(400).end('state mismatch');\n        return;\n      }\n      const code = url.searchParams.get('code');\n      const t = await tokenRequest({ grant_type: 'authorization_code', code, redirect_uri: REDIRECT_URI });\n      const jwt = JSON.parse(Buffer.from(t.access_token.split('.')[1], 'base64url'));\n      log(`認可 OK（${jwt.sub}・scope ${jwt.scopes.join(' ')}）トークンを ${TOKEN} に保存`);\n      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });\n      res.end(page('＠ベリーネットの API を認可しました', `scope: ${jwt.scopes.join(' ')} — このタブは閉じてかまいません。`));\n      return;\n    }\n    if (url.pathname === '/webhook' && req.method === 'POST') {\n      const raw = await body(req);\n      if (!verify(raw, req.headers['x-eccube-signature'])) {\n        log('WebHook 署名が一致しません → 401');\n        res.writeHead(401).end();\n        return;\n      }\n      res.writeHead(200).end(); // 先に 200 を返し、処理はそのあと\n      const events = JSON.parse(raw);\n      log(`WebHook ${events.map((e) => `${e.entity}#${e.id} ${e.action}`).join(', ')}`);\n      for (const id of new Set(events.filter((e) => e.entity === 'order').map((e) => e.id))) {\n        await pick(id).catch((e) => log(`受注 ${id} 失敗: ${e.message}`));\n      }\n      return;\n    }\n    res.writeHead(404).end();\n  }).listen(new URL(REDIRECT_URI).port, () => log(`store-link ${new URL(REDIRECT_URI).origin}（/callback /webhook）`));\n}\n\nif (cmd === 'authorize') {\n  const state = crypto.randomBytes(8).toString('hex');\n  fs.writeFileSync('var/state', state);\n  const q = new URLSearchParams({ response_type: 'code', client_id: CLIENT_ID, redirect_uri: REDIRECT_URI, scope: 'read write', state });\n  console.log(`${EC_URL}/admin/authorize?${q}`);\n}\n\nif (cmd === 'stock') {\n  // POS の販売・取置：商品コード（店舗のバーコード）ごとの在庫数。中古品は 1 点もの\n  for (const row of readCsv(arg)) {\n    try {\n      const { updateProductStock: p } = await api(gql('update-stock'), { code: row.商品コード, stock: Number(row.在庫数) });\n      log(`在庫 ${p.code} → ${p.stock}（${row.区分}・店舗 ${row.店舗}）`);\n    } catch (e) {\n      log(`在庫 ${row.商品コード} 失敗: ${e.message}`);\n      process.exitCode = 1;\n    }\n  }\n}\n\nif (cmd === 'orders') {\n  // WebHook が届かなかったときの取りこぼし対策：新規受付の注文をまとめて確認\n  try {\n    const { orders } = await api(gql('orders'));\n    log(`新規受付 ${orders.nodes.length} 件（出荷指示済み ${orders.nodes.filter((o) => picked.has(o.id)).length} 件）`);\n    for (const o of orders.nodes) await pick(o.id);\n  } catch (e) {\n    log(`取りこぼし確認 失敗: ${e.message}`);\n    process.exitCode = 1;\n  }\n}\n\nif (cmd === 'ship') {\n  // 店舗の出荷実績：出荷 ID・配送業者・お問い合わせ番号 → 出荷済み・出荷完了メール\n  for (const row of readCsv(arg)) {\n    try {\n      const { updateShipped: s } = await api(gql('update-shipped'), {\n        id: row.出荷ID, delivery: row.配送業者, tracking: row.お問い合わせ番号, note: `店舗 ${row.店舗} から出荷`,\n      });\n      log(`出荷 受注 ${row.受注番号}（出荷 ID ${s.id}）${s.shipping_delivery_name} ${s.tracking_number} メール送信 ${s.mail_send_date ? '済' : '-'}`);\n    } catch (e) {\n      log(`出荷 受注 ${row.受注番号} 失敗: ${e.message}`);\n      process.exitCode = 1;\n    }\n  }\n}\n"},"blocks":{"A":"/* ---------------------------------------------------------- 在庫台帳・出荷指示 */\nconst ledger = Object.fromEntries(readCsv('data/ledger.csv').map((r) => [r.商品コード, r]));\nconst picked = new Set(fs.existsSync(PICKED) ? JSON.parse(fs.readFileSync(PICKED, 'utf8')) : []);\n\nasync function pick(id) {\n  if (picked.has(String(id))) return;\n  const { order } = await api(gql('order'), { id });\n  if (order.OrderStatus.id !== '1') return; // 新規受付だけ（購入処理中の仮受注は除く）\n  for (const s of order.Shippings) {\n    for (const item of s.OrderItems.filter((i) => i.product_code)) {\n      const at = ledger[item.product_code];\n      log(`出荷指示 受注 ${order.order_no} → 店舗 ${at.店舗}（棚 ${at.棚番}）${item.product_name} 出荷 ID ${s.id}`);\n      fs.mkdirSync('outbox', { recursive: true });\n      fs.appendFileSync(`outbox/picking-${at.店舗}.csv`,\n        [order.order_no, s.id, item.product_code, item.product_name, at.棚番].join(',') + '\\n');\n    }\n  }\n  picked.add(String(id));\n  fs.writeFileSync(PICKED, JSON.stringify([...picked]));\n}\n\n/* ---------------------------------------------------------- WebHook（X-ECCUBE-Signature） */\nfunction verify(raw, sig) {\n  const mine = crypto.createHmac('sha256', WEBHOOK_SECRET).update(raw).digest('hex');\n  return typeof sig === 'string' && sig.length === mine.length\n    && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(mine));\n}\n\n","B":"    if (url.pathname === '/webhook' && req.method === 'POST') {\n      const raw = await body(req);\n      if (!verify(raw, req.headers['x-eccube-signature'])) {\n        log('WebHook 署名が一致しません → 401');\n        res.writeHead(401).end();\n        return;\n      }\n      res.writeHead(200).end(); // 先に 200 を返し、処理はそのあと\n      const events = JSON.parse(raw);\n      log(`WebHook ${events.map((e) => `${e.entity}#${e.id} ${e.action}`).join(', ')}`);\n      for (const id of new Set(events.filter((e) => e.entity === 'order').map((e) => e.id))) {\n        await pick(id).catch((e) => log(`受注 ${id} 失敗: ${e.message}`));\n      }\n      return;\n    }\n","C":"if (cmd === 'orders') {\n  // WebHook が届かなかったときの取りこぼし対策：新規受付の注文をまとめて確認\n  try {\n    const { orders } = await api(gql('orders'));\n    log(`新規受付 ${orders.nodes.length} 件（出荷指示済み ${orders.nodes.filter((o) => picked.has(o.id)).length} 件）`);\n    for (const o of orders.nodes) await pick(o.id);\n  } catch (e) {\n    log(`取りこぼし確認 失敗: ${e.message}`);\n    process.exitCode = 1;\n  }\n}\n\n","D":"if (cmd === 'ship') {\n  // 店舗の出荷実績：出荷 ID・配送業者・お問い合わせ番号 → 出荷済み・出荷完了メール\n  for (const row of readCsv(arg)) {\n    try {\n      const { updateShipped: s } = await api(gql('update-shipped'), {\n        id: row.出荷ID, delivery: row.配送業者, tracking: row.お問い合わせ番号, note: `店舗 ${row.店舗} から出荷`,\n      });\n      log(`出荷 受注 ${row.受注番号}（出荷 ID ${s.id}）${s.shipping_delivery_name} ${s.tracking_number} メール送信 ${s.mail_send_date ? '済' : '-'}`);\n    } catch (e) {\n      log(`出荷 受注 ${row.受注番号} 失敗: ${e.message}`);\n      process.exitCode = 1;\n    }\n  }\n}\n","HO":"//   node link.mjs orders         新規受付の注文の取りこぼし確認（定期実行）\n","HS":"//   node link.mjs ship <csv>     店舗の出荷実績 → updateShipped（出荷完了メール）\n","BUG":["req.headers['x-eccube-signature']","req.headers['X-ECCUBE-Signature']"]},"stockV1":"# 店舗の在庫数を EC へ\nmutation UpdateStock($code: String!, $stock: Int!) {\n  updateProductStock(code: $code, stock: $stock) {\n    code\n    stock\n    stock_unlimited\n  }\n}\n","core":{"app/Plugin/Api42/GraphQL/Mutation/UpdateProductStockMutation.php":"<?php\n\n/*\n * This file is part of EC-CUBE\n *\n * Copyright(c) EC-CUBE CO.,LTD. All Rights Reserved.\n *\n * http://www.ec-cube.co.jp/\n *\n * For the full copyright and license information, please view the LICENSE\n * file that was distributed with this source code.\n */\n\nnamespace Plugin\\Api42\\GraphQL\\Mutation;\n\nuse Doctrine\\ORM\\EntityManagerInterface;\nuse Eccube\\Entity\\ProductClass;\nuse Eccube\\Repository\\ProductClassRepository;\nuse GraphQL\\Type\\Definition\\Type;\nuse Plugin\\Api42\\GraphQL\\Error\\InvalidArgumentException;\nuse Plugin\\Api42\\GraphQL\\Mutation;\nuse Plugin\\Api42\\GraphQL\\Types;\n\nclass UpdateProductStockMutation implements Mutation\n{\n    /**\n     * @var Types\n     */\n    private $types;\n\n    /**\n     * @var ProductClassRepository\n     */\n    private $productClassRepository;\n\n    /**\n     * @var EntityManagerInterface\n     */\n    private $entityManager;\n\n    public function __construct(\n        Types $types,\n        ProductClassRepository $productClassRepository,\n        EntityManagerInterface $entityManager\n    ) {\n        $this->types = $types;\n        $this->productClassRepository = $productClassRepository;\n        $this->entityManager = $entityManager;\n    }\n\n    public function getName()\n    {\n        return 'updateProductStock';\n    }\n\n    public function getMutation()\n    {\n        return  [\n            'type' => $this->types->get(ProductClass::class),\n            'args' => [\n                'code' => [\n                    'type' => Type::nonNull(Type::string()),\n                    'description' => trans('api.update_product_stock.args.description.product_code'),\n                ],\n                'stock' => [\n                    'type' => Type::int(),\n                    'description' => trans('api.update_product_stock.args.description.stock'),\n                ],\n                'stock_unlimited' => [\n                    'type' => Type::nonNull(Type::boolean()),\n                    'description' => trans('api.update_product_stock.args.description.stock_unlimited'),\n                ],\n            ],\n            'resolve' => [$this, 'updateProductStock'],\n        ];\n    }\n\n    public function updateProductStock($root, $args)\n    {\n        $ProductClasses = $this->productClassRepository->findBy(['code' => $args['code']]);\n\n        // 更新対象の商品規格をチェック\n        if (count($ProductClasses) < 1) {\n            throw new InvalidArgumentException('code: No ProductClass found;');\n        }\n        if (count($ProductClasses) > 1) {\n            throw new InvalidArgumentException('code: Multiple ProductClass found;');\n        }\n\n        /** @var ProductClass $ProductClass */\n        $ProductClass = current($ProductClasses);\n        $productStock = $ProductClass->getProductStock();\n\n        if ($args['stock_unlimited']) {\n            // 在庫無制限の場合、在庫数の指定があればエラー\n            if (array_key_exists('stock', $args)) {\n                throw new InvalidArgumentException('stock: Cannot update stock with stock unlimited;');\n            }\n\n            // 更新\n            $ProductClass->setStockUnlimited(true);\n            $ProductClass->setStock(null);\n            $productStock->setStock(null);\n        } else {\n            // 在庫制限がある場合、在庫数の指定がなければエラー\n            if (!array_key_exists('stock', $args)) {\n                throw new InvalidArgumentException('stock: stock is required when stock limited;');\n            }\n            if ($args['stock'] < 0) {\n                throw new InvalidArgumentException('stock: stock must be a positive integer;');\n            }\n\n            // 更新\n            $ProductClass->setStockUnlimited(false);\n            $ProductClass->setStock($args['stock']);\n            $productStock->setStock($args['stock']);\n        }\n\n        $this->productClassRepository->save($ProductClass);\n        $this->entityManager->flush();\n\n        return $ProductClass;\n    }\n}","app/Plugin/Api42/Service/WebHookService.php":"<?php\n\n/*\n * This file is part of EC-CUBE\n *\n * Copyright(c) EC-CUBE CO.,LTD. All Rights Reserved.\n *\n * http://www.ec-cube.co.jp/\n *\n * For the full copyright and license information, please view the LICENSE\n * file that was distributed with this source code.\n */\n\nnamespace Plugin\\Api42\\Service;\n\nuse Eccube\\Util\\StringUtil;\nuse GuzzleHttp\\Client;\nuse GuzzleHttp\\Exception\\TransferException;\nuse GuzzleHttp\\Pool;\nuse GuzzleHttp\\Psr7\\Request;\nuse GuzzleHttp\\Psr7\\Response;\nuse Plugin\\Api42\\Entity\\WebHook;\nuse Plugin\\Api42\\Repository\\WebHookRepository;\nuse Symfony\\Component\\EventDispatcher\\EventSubscriberInterface;\nuse Symfony\\Component\\HttpKernel\\Event\\ResponseEvent ;\nuse Symfony\\Component\\HttpKernel\\KernelEvents;\nuse Symfony\\Component\\Routing\\RouterInterface;\n\nclass WebHookService implements EventSubscriberInterface\n{\n    /**\n     * @var RouterInterface\n     */\n    private RouterInterface $router;\n\n    /**\n     * @var WebHookRepository\n     */\n    private WebHookRepository $webHookRepository;\n\n    /**\n     * @var WebHookEvents\n     */\n    private WebHookEvents $webHookEvents;\n\n    /**\n     * WebHookService constructor.\n     */\n    public function __construct(RouterInterface $router, WebHookRepository $webHookRepository, WebHookEvents $webHookEvents)\n    {\n        $this->router = $router;\n        $this->webHookRepository = $webHookRepository;\n        $this->webHookEvents = $webHookEvents;\n    }\n\n    public static function getSubscribedEvents()\n    {\n        return [\n            KernelEvents::RESPONSE => 'fire',\n        ];\n    }\n\n    public function fire(ResponseEvent $event)\n    {\n        if (!$event->isMainRequest()) {\n            return;\n        }\n\n        $events = $this->webHookEvents->toArray();\n\n        if ($events) {\n            $payload = json_encode($events);\n\n            /** @var WebHook[] $availableWebHooks */\n            $availableWebHooks = $this->webHookRepository->findBy(['enabled' => true]);\n\n            $requests = array_map(function (WebHook $WebHook) use ($payload) {\n                return $this->createRequest($payload, $WebHook);\n            }, $availableWebHooks);\n\n            $client = new Client();\n            $pool = new Pool($client, $requests, [\n                'concurrency' => 5,\n                'options' => [\n                    'connect_timeout' => 1,\n                    'timeout' => 5,\n                    'allow_redirects' => false,\n                ],\n                'fulfilled' => function (Response $reason, $index) use ($availableWebHooks) {\n                    log_info('WebHook request successful.', ['Payload URL' => $availableWebHooks[$index]->getPayloadUrl()]);\n                },\n                'rejected' => function (TransferException $e, $index) use ($availableWebHooks) {\n                    log_error($e->getMessage(), ['Payload URL' => $availableWebHooks[$index]->getPayloadUrl()]);\n                },\n            ]);\n            $p = $pool->promise();\n            $p->wait();\n        }\n    }\n\n    private function createRequest($payload, $WebHook)\n    {\n        $headers = [\n            'Content-Type' => 'application/json',\n            'X-ECCUBE-URL' => $this->router->generate('homepage', [], RouterInterface::ABSOLUTE_URL),\n        ];\n        if (StringUtil::isNotBlank($WebHook->getSecret())) {\n            $headers['X-ECCUBE-Signature'] = hash_hmac('sha256', $payload, $WebHook->getSecret());\n        }\n\n        return new Request('POST', $WebHook->getPayloadUrl(), $headers, $payload);\n    }\n}","vendor/league/oauth2-server-bundle/src/Repository/ClientRepository.php":"<?php\n\ndeclare(strict_types=1);\n\nnamespace League\\Bundle\\OAuth2ServerBundle\\Repository;\n\nuse League\\Bundle\\OAuth2ServerBundle\\Entity\\Client as ClientEntity;\nuse League\\Bundle\\OAuth2ServerBundle\\Manager\\ClientManagerInterface;\nuse League\\Bundle\\OAuth2ServerBundle\\Model\\AbstractClient;\nuse League\\OAuth2\\Server\\Repositories\\ClientRepositoryInterface;\n\nfinal class ClientRepository implements ClientRepositoryInterface\n{\n    /**\n     * @var ClientManagerInterface\n     */\n    private $clientManager;\n\n    public function __construct(ClientManagerInterface $clientManager)\n    {\n        $this->clientManager = $clientManager;\n    }\n\n    /**\n     * {@inheritdoc}\n     */\n    public function getClientEntity($clientIdentifier)\n    {\n        $client = $this->clientManager->find($clientIdentifier);\n\n        if (null === $client) {\n            return null;\n        }\n\n        return $this->buildClientEntity($client);\n    }\n\n    /**\n     * {@inheritdoc}\n     */\n    public function validateClient($clientIdentifier, $clientSecret, $grantType): bool\n    {\n        $client = $this->clientManager->find($clientIdentifier);\n\n        if (null === $client) {\n            return false;\n        }\n\n        if (!$client->isActive()) {\n            return false;\n        }\n\n        if (!$this->isGrantSupported($client, $grantType)) {\n            return false;\n        }\n\n        if (!$client->isConfidential() || hash_equals((string) $client->getSecret(), (string) $clientSecret)) {\n            return true;\n        }\n\n        return false;\n    }\n\n    private function buildClientEntity(AbstractClient $client): ClientEntity\n    {\n        $clientEntity = new ClientEntity();\n        $clientEntity->setName($client->getName());\n        $clientEntity->setIdentifier($client->getIdentifier());\n        $clientEntity->setRedirectUri(array_map('strval', $client->getRedirectUris()));\n        $clientEntity->setConfidential($client->isConfidential());\n        $clientEntity->setAllowPlainTextPkce($client->isPlainTextPkceAllowed());\n\n        return $clientEntity;\n    }\n\n    private function isGrantSupported(AbstractClient $client, ?string $grant): bool\n    {\n        if (null === $grant) {\n            return true;\n        }\n\n        $grants = $client->getGrants();\n\n        if (empty($grants)) {\n            return true;\n        }\n\n        return \\in_array($grant, $client->getGrants());\n    }\n}"}};
  if (typeof module !== 'undefined' && module.exports) module.exports = SRC; else root.TB_SRC = SRC;
})(this);
